#include <bits/stdc++.h>
using namespace std;

struct CharData {
    char chr;
    int value;
    int idx;
    CharData(char c, int v, int i) : chr(c), value(v), idx(i) {}
};

bool isAntiPalindromic(const std::vector<char>& arr) {
    int len = arr.size();
    for (int i = 0; i < len / 2; i++) {
        if (arr[i] == arr[len - i - 1]) {
            return false;
        }
    }
    return true;
}

void swapCharsAndValues(std::vector<char>& arr, std::vector<int>& vals, int i) {
    std::swap(arr[i], arr[arr.size() - i - 1]);
    std::swap(vals[i], vals[vals.size() - i - 1]);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int size;
    cin >> size;
    cin.ignore();
    std::string str;
    getline(cin, str);
    str.erase(str.begin(), std::find_if(str.begin(), str.end(), [](unsigned char ch) { return !isspace(ch); }));
    std::vector<char> array(str.begin(), str.end());

    std::vector<int> values(size);
    for (int i = 0; i < size; i++) {
        cin >> values[i];
    }
    cin.ignore();

    std::vector<CharData> mismatchList;
    std::vector<CharData> dataList;
    for (int i = 0; i < size / 2; i++) {
        if (values[i] > values[size - i - 1]) {
            swapCharsAndValues(array, values, i);
        }
        CharData cd(array[i], values[i], i);
        if (array[i] == array[size - i - 1]) {
            mismatchList.push_back(cd);
        }
        dataList.push_back(cd);
    }

    std::sort(dataList.begin(), dataList.end(), [](const CharData& a, const CharData& b) {
        return a.value < b.value;
    });

    int totalCost = 0;
    if (!isAntiPalindromic(array)) {
        if (mismatchList.size() == 1) {
            CharData wrongChar = mismatchList[0];
            for (const auto& cd : dataList) {
                if (cd.chr != wrongChar.chr && array[size - cd.idx - 1] != wrongChar.chr) {
                    totalCost = wrongChar.value + cd.value;
                    break;
                }
            }
        } else if (mismatchList.size() > 1) {
            std::unordered_map<char, int> countMap;
            for (const auto& cd : mismatchList) {
                countMap[cd.chr]++;
            }
            int maxCount = 0;
            for (const auto& kv : countMap) {
                if (kv.second > maxCount) maxCount = kv.second;
            }
            std::vector<CharData> appendList;
            while (maxCount * 2 > mismatchList.size() + (int)appendList.size()) {
                auto maxEntry = std::max_element(countMap.begin(), countMap.end(),
                    [](const std::pair<char, int>& a, const std::pair<char, int>& b) {
                        return a.second < b.second;
                    });
                char maxChar = maxEntry->first;
                for (const auto& cd : dataList) {
                    if (cd.chr != maxChar && array[size - cd.idx - 1] != maxChar &&
                        std::find(mismatchList.begin(), mismatchList.end(), cd) == mismatchList.end() &&
                        std::find(appendList.begin(), appendList.end(), cd) == appendList.end()) {
                        appendList.push_back(cd);
                        break;
                    }
                }
                // Recompute maxCount
                countMap.clear();
                for (const auto& cd : mismatchList) {
                    countMap[cd.chr]++;
                }
                maxCount = 0;
                for (const auto& kv : countMap) {
                    if (kv.second > maxCount) maxCount = kv.second;
                }
            }
            int sumMismatch = 0;
            for (const auto& c : mismatchList) sumMismatch += c.value;
            int sumAppend = 0;
            for (const auto& c : appendList) sumAppend += c.value;
            totalCost = sumMismatch + sumAppend;
        }
    }
    int sumValues = std::accumulate(values.begin(), values.end(), 0);
    std::cout << sumValues - totalCost << "\n";

    return 0;
}

